/* Option accessors (inline). g_aeopid takes their addresses, which is why out-of-line copies of them exist in the
 * linkonce area; g_aeopid's TU (class_registry.cpp) emits them that way. See docs/guides/tu-merging.md
 * "Inline functions and linkonce copies". Free functions (not members): see there why. Names (inferred): what they return. */
/* The "ensure" accessors of these classes return the start of the class's own fields (the end of its base part); the
 * option records address fields relative to it. The classes have no header yet, so only their names are used. */
struct CID12; struct CID27; struct CID34; struct CID35; struct CID38; struct CID39; struct HND; struct PIPE; struct RAIL;
inline void *GetCid12OwnFields(CID12 *p);    /* CID12 : SHAPE */
inline void *GetCid34OwnFields(CID34 *p);      /* CID34 : XFM */
inline void *GetCid38OwnFields(CID38 *p);      /* CID38 : XFM */
inline void *GetCid35OwnFields(CID35 *p);      /* CID35 : XFM */
inline void *GetCid27OwnFields(CID27 *p);      /* CID27 : VOL */
inline void *GetHndOwnFields(HND *phnd);  /* HND : TARGET */
inline void *GetPipeOwnFields(PIPE *ppipe);  /* PIPE : SHAPE */
inline void *GetRailOwnFields(RAIL *prail);  /* RAIL : SHAPE */
inline void *GetCid39OwnFields(CID39 *p);      /* CID39 : XFM */

/* The GRABSPOT owner getters: slot 6 of each class's GRABSPOT vtable (the entry's delta brings `this` back to the
 * object's start) returns the object itself; GRABSPOT's own slot 6 (GetGrabspotOwner) returns 0. In the linkonce area
 * each sits right before its class's ensure accessor above (BARREL's in sly2/so.h). HYPOTHESIS: inline virtual
 * overrides in the original; free inline functions here, emitted by the key TU of each class, whose vtable names
 * them through classes.h's GetOwner labels (a label equal to the mangled name makes g++ emit the inline function). */
inline void *GetCid12GrabspotOwner(CID12 *p) { return p; }
inline void *GetCid34GrabspotOwner(CID34 *p) { return p; }
inline void *GetCid38GrabspotOwner(CID38 *p) { return p; }
inline void *GetCid35GrabspotOwner(CID35 *p) { return p; }
inline void *GetCid27GrabspotOwner(CID27 *p) { return p; }
inline void *GetHndGrabspotOwner(HND *phnd) { return phnd; }
inline void *GetPipeGrabspotOwner(PIPE *ppipe) { return ppipe; }
inline void *GetRailGrabspotOwner(RAIL *prail) { return prail; }
inline void *GetCid39GrabspotOwner(CID39 *p) { return p; }

/* SOPART: one collision part of an SO: its transform, mesh (local and world copies), BSP and damage settings (here
   rather than in so.h so that files can read parts without so.h; cm.cpp).
   Layout from src/game/engine/graphics/pipeline/glob/LoadGlobsetFromBrx__FP7GLOBSETP2SOP18CBinaryInputStream.cpp (9 copies in Lilly ports) */
struct SOPART
{
      XF *transform; /* transform the part moves with */
      SO *owner; /* owning solid object */
      float radius;
      OID oid;   /* oid of the part */
      LVO *plvo;   /* local vertex data */
      short damage; /* damage (hit points) dealt or taken by the part (inferred: dhp = delta hit points) */
      ulong unknownFlag10A : 1;   /* possibly collectsZaps (low-confidence guess: mark.cpp: parts with zap kinds (unknownFlag10A / zapKindFlags) collect zap contacts) */
               ulong unknownFlag10B : 1;   /* possibly isSphere (low-confidence guess: so.cpp view: radius applies to unknownFlag10B parts; mark.cpp sphere tests) */
               ulong isHidden : 1;  /* part is hidden */
               ulong hasPlaces : 1;   /* the part carries hero places (RemoveSoPartFromTree then calls RemoveSwPlacesOf; places.cpp) */
               ulong unknownBits10A : 12;
      uint zapKindFlags; /* zap kinds (damage types) the part delivers or accepts */
      int unknown1C;   /* possibly numSphereVertices (low-confidence guess: compared with meshLocal.cpos in mark.cpp) */
      union
      {
            MATRIX4 matWorld;   /* world matrix of the part */
            MATRIX4Q matqWorld;   /* its rows as quadwords (row 3: the part's world position; water.cpp) */
      };
      DLE dle;   /* link in the physics tree's part list */
      BSPC bspc;   /* BSP of the part mesh */
      GEOM meshLocal;   /* part mesh (local) */
      GEOM meshWorld;   /* part mesh (world, updated when stale) */
      int meshStamp;    /* frame stamp of the world mesh */
      int worldStamp;    /* frame stamp of the world matrix */
};

